describe('Product Catalog Navigation - Return to Catalogue', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.login('standard_user', 'secret_sauce');
  });

  it('should navigate to product detail page and return to catalogue', () => {
    // Verify initial catalogue page is loaded
    cy.get('[data-testid="catalogue-title"]').should('contain', 'Products');

    // Click on the first product name to navigate to detail page
    cy.get('[data-testid="inventory-item-name"]').first().click();

    // Verify we are on product detail page
    cy.url().should('include', '/inventory-item.html');
    cy.get('[data-testid="product-name"]').should('be.visible');

    // Verify product detail page URL contains 'inventory-item.html'
    cy.url().should('include', '/inventory-item.html');

    // Click the back button to return to catalogue
    cy.get('[data-testid="back-to-products"]').click();

    // Verify we are back on catalogue page
    cy.url().should('include', '/inventory.html');

    // Verify catalogue title is visible
    cy.get('[data-testid="catalogue-title"]').should('contain', 'Products');
  });

  it('should handle edge case: clicking back button when already on catalogue', () => {
    // Verify initial catalogue page is loaded
    cy.get('[data-testid="catalogue-title"]').should('contain', 'Products');

    // Click the back button to verify it does not navigate away
    cy.get('[data-testid="back-to-products"]').click();

    // Verify URL remains the same
    cy.url().should('include', '/inventory.html');

    // Verify catalogue title is still visible
    cy.get('[data-testid="catalogue-title"]').should('contain', 'Products');

    // Verify back button is still clickable
    cy.get('[data-testid="back-to-products"]').should('be.visible');
  });
});
